namespace sv_9380eb88b7604929a7895eb289b34f83.Services;

public class Warehouse
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new Warehouse { Id = "WH-A", Name = "Warehouse A" },
        new Warehouse { Id = "WH-B", Name = "Warehouse B" },
        new Warehouse { Id = "WH-C", Name = "Warehouse C" },
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public Warehouse CurrentWarehouse =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId);

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_9380eb88b7604929a7895eb289b34f83.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts
/// and notifies all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activeSubscribers;

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Raised on every poll tick so ALL subscribed components can refresh.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query — returns a random count 0-15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes visible.
    /// Starts the timer on the first subscriber.
    /// </summary>
    public void StartPolling()
    {
        _activeSubscribers++;
        if (_activeSubscribers == 1)
            StartTimer();
    }

    /// <summary>
    /// Call when a polling component is disposed / leaves the page.
    /// Stops the timer when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
        if (_activeSubscribers == 0)
            StopTimer();
    }

    private void StartTimer()
    {
        StopTimer();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start, then every 10 seconds.
        await FetchAndNotifyAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await FetchAndNotifyAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When the warehouse changes, immediately re-fetch so every
        // subscriber sees data for the new warehouse right away.
        if (_activeSubscribers > 0)
            await FetchAndNotifyAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        StopTimer();
    }
}

