@using sv_9380eb88b7604929a7895eb289b34f83.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 32rem;">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouse.Name</strong> — Inventory Alerts
    </div>
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Items:
            <span class="badge rounded-pill @BadgeClass fs-5">@AlertService.LatestLowStockCount</span>
        </h5>
        <p class="card-text text-muted">
            Refreshes automatically every 10 seconds. Switch warehouses using the dropdown above.
        </p>
    </div>
    <div class="card-footer text-muted">
        Polling is <strong>active</strong> while this page is open.
    </div>
</div>

@code {
    private string BadgeClass => AlertService.LatestLowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        _ => "bg-success"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChangedAsync;
        AlertService.OnAlertDataChanged += OnStateChangedAsync;

        // This page drives the polling lifecycle.
        AlertService.StartPolling();
    }

    private async Task OnStateChangedAsync()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChange -= OnStateChangedAsync;
        AlertService.OnAlertDataChanged -= OnStateChangedAsync;
    }
}

